import { type FormEvent, useCallback, useEffect, useState } from 'react'

import { AiBadge } from '../../components/shared/AiBadge'
import { StatusBadge } from '../../components/shared/StatusBadge'
import { EmptyState, ErrorState, LoadingState } from '../../components/shared/ViewState'
import {
  apiClient,
  type AgentTraceDto,
  type ApprovedGuidanceDto,
  type EpisodeDto,
  type FamilyDto,
  type MemberDto,
  type PagedResult,
  type TriageCaseDto,
} from '../../services/apiClient'
import { AgentPipeline } from './AgentPipeline'
import { terminalStatuses } from './pipelineStages'

type TriageStatusDto = { id: string; status: string; priority: string; failureCode?: string | null }

const POLL_MS = 3000

export function TriagePage() {
  const [members, setMembers] = useState<MemberDto[]>([])
  const [familyId, setFamilyId] = useState('')
  const [cases, setCases] = useState<TriageCaseDto[]>([])
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [selectedId, setSelectedId] = useState('')
  const [caseStatus, setCaseStatus] = useState<TriageStatusDto | null>(null)
  const [traces, setTraces] = useState<AgentTraceDto[]>([])
  const [guidance, setGuidance] = useState<ApprovedGuidanceDto | null>(null)
  const [submitting, setSubmitting] = useState(false)
  const [message, setMessage] = useState('')

  const loadCases = useCallback(async (id: string) => {
    const { data } = await apiClient.get<PagedResult<TriageCaseDto>>(`/families/${id}/triage-cases`, { params: { page: 1, pageSize: 20 } })
    setCases(data.items)
    setSelectedId((current) => current || data.items[0]?.id || '')
  }, [])

  const load = useCallback(async () => {
    setStatus('loading')
    try {
      const { data: family } = await apiClient.get<FamilyDto>('/families/me')
      setMembers(family.members); setFamilyId(family.id)
      await loadCases(family.id)
      setStatus('ready')
    } catch { setStatus('error') }
  }, [loadCases])
  useEffect(() => { void load() }, [load])

  const refreshCase = useCallback(async (caseId: string) => {
    const [statusRes, tracesRes] = await Promise.all([
      apiClient.get<TriageStatusDto>(`/triage-cases/${caseId}/status`),
      apiClient.get<AgentTraceDto[]>(`/triage-cases/${caseId}/traces`),
    ])
    setCaseStatus(statusRes.data); setTraces(tracesRes.data)
    // Patient-visible text comes only from the approval gate endpoint (Rule 2).
    if (statusRes.data.status.startsWith('Approved')) {
      const { data } = await apiClient.get<ApprovedGuidanceDto>(`/triage-cases/${caseId}/approved-guidance`)
      setGuidance(data)
    } else {
      setGuidance(null)
    }
    return statusRes.data.status
  }, [])

  useEffect(() => {
    if (!selectedId) return
    let cancelled = false
    let timer: ReturnType<typeof setTimeout> | undefined
    const tick = async () => {
      try {
        const current = await refreshCase(selectedId)
        if (!cancelled && !terminalStatuses.includes(current)) timer = setTimeout(() => void tick(), POLL_MS)
      } catch {
        if (!cancelled) setMessage('Case progress could not be loaded. Retry by selecting the case again.')
      }
    }
    setCaseStatus(null); setTraces([]); setGuidance(null)
    void tick()
    return () => { cancelled = true; if (timer) clearTimeout(timer) }
  }, [selectedId, refreshCase])

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const symptoms = String(form.get('symptoms') ?? '').split(',').map((item) => item.trim()).filter(Boolean)
    if (symptoms.length === 0) { setMessage('Enter at least one symptom.'); return }
    setSubmitting(true); setMessage('')
    try {
      const { data: episode } = await apiClient.post<EpisodeDto>(`/members/${form.get('memberId')}/episodes`, {
        symptoms,
        durationDays: Number(form.get('durationDays')),
        severity: Number(form.get('severity')),
        notes: String(form.get('notes') ?? '').trim() || null,
      })
      const { data: triageCase } = await apiClient.post<TriageCaseDto>(`/episodes/${episode.id}/triage`)
      setMessage('Submitted. The agent pipeline is running; progress updates below.')
      await loadCases(familyId)
      setSelectedId(triageCase.id)
    } catch {
      setMessage('Submission failed. Check the member and symptoms, then retry.')
    } finally { setSubmitting(false) }
  }

  const failedSafe = caseStatus?.status === 'FailedSafe' || caseStatus?.status === 'Escalated' || caseStatus?.priority === 'Emergency'

  return (
    <div className="page-stack">
      <header className="page-header">
        <div>
          <p className="eyebrow">Agentic clinical triage <AiBadge /></p>
          <h1>AI triage</h1>
          <p>Describe symptoms. Distinct agents plan, gather consented context, analyse and validate. A licensed doctor approves before you see any result. This service never diagnoses.</p>
        </div>
      </header>

      {status === 'loading' ? <LoadingState label="Loading triage interface" /> : status === 'error' ? <ErrorState message="Triage interface could not be loaded." onRetry={() => void load()} /> : (
        <>
          <section className="panel">
            <h2>New symptom episode</h2>
            <p className="muted">If this is an emergency, call 1990 (Suwa Seriya) or go to the nearest emergency unit now. Do not wait for this service.</p>
            <form className="form-grid" onSubmit={(event) => void submit(event)}>
              <label>Member<select name="memberId" required>{members.map((member) => <option key={member.id} value={member.id}>{member.displayName}</option>)}</select></label>
              <label>Symptoms (comma separated)<input name="symptoms" required maxLength={500} placeholder="e.g. mild headache, fatigue" /></label>
              <label>Duration (days)<input name="durationDays" type="number" min={0} max={365} defaultValue={1} required /></label>
              <label>Severity (1–10)<input name="severity" type="number" min={1} max={10} defaultValue={3} required /></label>
              <label>Notes<textarea name="notes" maxLength={1000} /></label>
              <button className="button button--primary" type="submit" disabled={submitting}>{submitting ? 'Submitting…' : 'Start AI triage'}</button>
            </form>
            {message && <p role="status">{message}</p>}
          </section>

          <section className="panel">
            <h2>Your triage cases</h2>
            {cases.length === 0 ? <EmptyState title="No triage cases yet" message="Submit a symptom episode to start the agent pipeline." /> : (
              <label>Case<select value={selectedId} onChange={(event) => setSelectedId(event.target.value)}>{cases.map((item) => <option key={item.id} value={item.id}>{new Date(item.createdAt).toLocaleString()} · {item.status}</option>)}</select></label>
            )}
          </section>

          {selectedId && (
            <section className="panel" aria-live="polite">
              <div className="panel-heading" style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--sp-3)', flexWrap: 'wrap' }}>
                <h2>Agent pipeline</h2>
                {caseStatus && <StatusBadge status={caseStatus.status} />}
              </div>
              {!caseStatus ? <LoadingState label="Loading pipeline progress" /> : <AgentPipeline traces={traces} caseStatus={caseStatus.status} />}
              {failedSafe && (
                <div className="referral-card" role="alert">
                  <h3>Please seek in-person care</h3>
                  <p>This case needs an in-person clinician. No automated guidance will be shown. For an emergency, call 1990 or go to the nearest emergency unit.</p>
                </div>
              )}
              {guidance && !failedSafe && (
                <div className="approved-card">
                  <h3>Doctor-approved guidance</h3>
                  <p>{guidance.finalAdvisory}</p>
                  <p className="muted">Approved {new Date(guidance.approvedAt).toLocaleString()} · {guidance.disclaimer}</p>
                </div>
              )}
            </section>
          )}
        </>
      )}
    </div>
  )
}
